window.SHARPS_NARRATION = {"manufacturing/ident":{"src":"manufacturing-ident.m4a","dur":6.03,"sents":[{"p":0,"w":"DANA","t":"This is Contain the Sharp.","s":0.0,"e":1.357},{"p":0,"w":"DANA","t":"Bloodborne Pathogens, Module 4.","s":1.677,"e":4.003},{"p":0,"w":"DANA","t":"I’m Dana, with Ray.","s":4.323,"e":5.713}],"env":"dxwpgfrunh75cwwnadsvuwxzuuljieutspomjb2000000000008sttsnc4ouvutvwb6jusrl65srddlqomkg7972000001sxuutobgvvuusl767tttrokf710000000002qttuyudrutuvvqnje4000005sul6bpttsrqomie710000000000"},"manufacturing/outro":{"src":"manufacturing-outro.m4a","dur":2.04,"sents":[{"p":0,"w":"DANA","t":"You may now continue the lesson.","s":0.0,"e":1.722}],"env":"lyzvyytttuxxtrsssl48putbcfvuxyywuhfspqrsrlhfdpnljd400000000000"},"manufacturing/c1base":{"src":"manufacturing-c1base.m4a","dur":83.97,"sents":[{"p":0,"w":"DANA","t":"The blade at the bench.","s":0.0,"e":1.103},{"p":0,"w":"DANA","t":"Ray, set it up for me.","s":1.423,"e":3.021},{"p":1,"w":"RAY","t":"You’re at your bench.","s":3.521,"e":4.88},{"p":1,"w":"RAY","t":"You’ve just changed out a used box-cutter blade.","s":5.2,"e":8.526},{"p":2,"w":"DANA","t":"Routine.","s":9.026,"e":9.707},{"p":3,"w":"RAY","t":"Completely routine.","s":10.207,"e":11.975},{"p":3,"w":"RAY","t":"The designated sharps container is down at the end of the line.","s":12.295,"e":16.422},{"p":3,"w":"RAY","t":"And the used blade is still sitting at your bench.","s":16.742,"e":19.748},{"p":4,"w":"DANA","t":"Let me ask the obvious one.","s":20.248,"e":21.994},{"p":4,"w":"DANA","t":"When I hear “sharps,”","s":22.314,"e":23.524},{"p":4,"w":"DANA","t":"I think needles.","s":23.844,"e":24.815},{"p":4,"w":"DANA","t":"This is a box cutter.","s":25.135,"e":26.329},{"p":5,"w":"RAY","t":"Good question, because the definition is wider than people expect.","s":26.829,"e":31.467},{"p":5,"w":"RAY","t":"Like a needle or any other sharp object, that blade is a sharp — because it can puncture or cut the skin, it’s a hazard.","s":31.787,"e":39.737},{"p":6,"w":"DANA","t":"Even if there’s nothing visible on it?","s":40.237,"e":42.115},{"p":7,"w":"RAY","t":"Whether or not it’s visibly contaminated.","s":42.615,"e":45.493},{"p":7,"w":"RAY","t":"An exposed blade left on a surface is a hazard to the next person who reaches for that spot.","s":45.813,"e":51.667},{"p":7,"w":"RAY","t":"That’s why the safe-handling procedure applies to every sharp, every time.","s":51.987,"e":57.17},{"p":8,"w":"DANA","t":"So what is the procedure?","s":57.67,"e":59.031},{"p":8,"w":"DANA","t":"Say it plainly.","s":59.351,"e":60.306},{"p":9,"w":"RAY","t":"Four things.","s":60.806,"e":62.085},{"p":9,"w":"RAY","t":"Plan how you’re going to dispose of it.","s":62.405,"e":64.878},{"p":9,"w":"RAY","t":"Use a safer alternative when one exists.","s":65.198,"e":68.156},{"p":9,"w":"RAY","t":"Activate any available safety feature.","s":68.476,"e":71.387},{"p":9,"w":"RAY","t":"And once it’s been used — don’t recap it, don’t bend it, don’t break it.","s":71.707,"e":76.921},{"p":9,"w":"RAY","t":"It goes directly into a designated sharps container.","s":77.241,"e":80.936},{"p":10,"w":"DANA","t":"Directly.","s":81.436,"e":82.045},{"p":11,"w":"RAY","t":"Directly.","s":82.545,"e":83.647}],"env":""},"manufacturing/c1rem":{"src":"manufacturing-c1rem.m4a","dur":61.92,"sents":[{"p":0,"w":"DANA","t":"The blade at the bench.","s":0.0,"e":1.103},{"p":0,"w":"DANA","t":"Let’s take this one slowly.","s":1.423,"e":2.96},{"p":1,"w":"RAY","t":"You’re cleaning up your workstation after changing a cutting blade.","s":3.46,"e":7.539},{"p":1,"w":"RAY","t":"The used blade is still in your hand, and you’re deciding how to handle it before you move on.","s":7.859,"e":13.585},{"p":2,"w":"DANA","t":"My instinct is to make it safer first.","s":14.085,"e":16.33},{"p":2,"w":"DANA","t":"Snap it.","s":16.65,"e":17.303},{"p":2,"w":"DANA","t":"Or set it down somewhere obvious.","s":17.623,"e":19.508},{"p":3,"w":"RAY","t":"That instinct makes sense — both of those feel like the responsible move.","s":20.008,"e":24.742},{"p":3,"w":"RAY","t":"What they don’t do is properly contain the sharp.","s":25.062,"e":28.404},{"p":3,"w":"RAY","t":"That’s the distinction.","s":28.724,"e":30.371},{"p":4,"w":"DANA","t":"Is there a wrapping step?","s":30.871,"e":32.134},{"p":5,"w":"RAY","t":"Depending on your facility’s procedures, you may need to wrap the exposed edge before disposal.","s":32.634,"e":39.047},{"p":5,"w":"RAY","t":"So check yours.","s":39.367,"e":40.774},{"p":5,"w":"RAY","t":"The rule underneath stays the same.","s":41.094,"e":43.46},{"p":5,"w":"RAY","t":"Once a sharp is used, don’t recap it, bend it, or break it.","s":43.78,"e":48.547},{"p":5,"w":"RAY","t":"Don’t leave it on a work surface, and don’t place it in general waste.","s":48.867,"e":53.44},{"p":6,"w":"DANA","t":"And instead.","s":53.94,"e":54.656},{"p":7,"w":"RAY","t":"Move it directly to a designated sharps container.","s":55.156,"e":58.787},{"p":7,"w":"RAY","t":"That’s the safe-handling procedure.","s":59.107,"e":61.601}],"env":""},"manufacturing/c1up":{"src":"manufacturing-c1up.m4a","dur":71.29,"sents":[{"p":0,"w":"DANA","t":"When the container is a walk away.","s":0.0,"e":1.778},{"p":0,"w":"DANA","t":"Ray, set it up for me.","s":2.098,"e":3.696},{"p":1,"w":"RAY","t":"You’ve just changed out a used box-cutter blade at your bench.","s":4.196,"e":8.066},{"p":1,"w":"RAY","t":"The designated sharps container is several workstations away.","s":8.386,"e":12.561},{"p":1,"w":"RAY","t":"Your line is about to restart.","s":12.881,"e":15.024},{"p":1,"w":"RAY","t":"And a coworker is waving you back.","s":15.344,"e":17.902},{"p":2,"w":"DANA","t":"That’s a real situation.","s":18.402,"e":19.794},{"p":3,"w":"RAY","t":"That’s the situation.","s":20.294,"e":22.021},{"p":4,"w":"DANA","t":"And here’s my honest read — setting it down at my own station doesn’t feel careless.","s":22.521,"e":27.195},{"p":4,"w":"DANA","t":"I can see it.","s":27.515,"e":28.347},{"p":4,"w":"DANA","t":"It’s mine.","s":28.667,"e":29.325},{"p":4,"w":"DANA","t":"I’ll take it down on my break.","s":29.645,"e":31.325},{"p":5,"w":"RAY","t":"That’s exactly how it feels.","s":31.825,"e":34.08},{"p":5,"w":"RAY","t":"You can see exactly where it is, and you’re planning to carry it down on your next scheduled break.","s":34.4,"e":40.43},{"p":5,"w":"RAY","t":"Nothing about that feels careless.","s":40.75,"e":43.18},{"p":6,"w":"DANA","t":"And yet.","s":43.68,"e":44.176},{"p":7,"w":"RAY","t":"The safe-handling procedure doesn’t change when work gets busy.","s":44.676,"e":48.771},{"p":7,"w":"RAY","t":"Once a sharp is used — don’t recap it, don’t bend it, don’t break it, and don’t set it aside for later.","s":49.091,"e":56.417},{"p":7,"w":"RAY","t":"It goes directly into a designated sharps container.","s":56.737,"e":60.432},{"p":8,"w":"DANA","t":"Even for a few minutes.","s":60.932,"e":62.217},{"p":9,"w":"RAY","t":"Leaving that blade at your workstation, even temporarily, creates a hazard for anyone who reaches for that spot before you get back.","s":62.717,"e":70.971}],"env":""},"manufacturing/c2base":{"src":"manufacturing-c2base.m4a","dur":82.03,"sents":[{"p":0,"w":"DANA","t":"Let’s talk about a sharps container that’s at the fill line.","s":0.0,"e":3.046},{"p":0,"w":"DANA","t":"Ray, this is all about what you notice when you’re following procedure.","s":3.366,"e":7.065},{"p":1,"w":"RAY","t":"It is.","s":7.565,"e":8.412},{"p":1,"w":"RAY","t":"Knowing what to do is one thing.","s":8.732,"e":10.906},{"p":1,"w":"RAY","t":"Spotting the condition is a separate skill.","s":11.226,"e":13.929},{"p":2,"w":"DANA","t":"Give me the scene.","s":14.429,"e":15.361},{"p":3,"w":"RAY","t":"You’re carrying a used sharp to a designated sharps container on the production floor.","s":15.861,"e":21.316},{"p":3,"w":"RAY","t":"You get close, and the container is full.","s":21.636,"e":24.546},{"p":4,"w":"DANA","t":"Full.","s":25.046,"e":25.466},{"p":5,"w":"RAY","t":"Full.","s":25.966,"e":26.748},{"p":5,"w":"RAY","t":"And on the way there, you passed a piece of contaminated glass sitting in a general-waste bin.","s":27.068,"e":32.827},{"p":6,"w":"DANA","t":"Those feel like two unrelated things to me.","s":33.327,"e":35.601},{"p":6,"w":"DANA","t":"One’s a container doing its job.","s":35.921,"e":37.804},{"p":6,"w":"DANA","t":"The other is something somebody else left.","s":38.124,"e":40.247},{"p":7,"w":"RAY","t":"They look nothing alike, and both are sharps hazards.","s":40.747,"e":44.362},{"p":8,"w":"DANA","t":"Start with the container.","s":44.862,"e":46.153},{"p":8,"w":"DANA","t":"Why does full count?","s":46.473,"e":47.682},{"p":9,"w":"RAY","t":"A sharps container at its fill line should no longer be used, because there’s less room to place another sharp safely without coming into contact with the sharps already inside.","s":48.182,"e":59.365},{"p":10,"w":"DANA","t":"And the glass in the bin?","s":59.865,"e":60.976},{"p":11,"w":"RAY","t":"A sharp left where it doesn’t belong — on a work surface, concealed in other material, or mixed into general waste — can put the next person who encounters it at risk.","s":61.476,"e":72.37},{"p":12,"w":"DANA","t":"So the skill here is seeing it.","s":72.87,"e":74.394},{"p":13,"w":"RAY","t":"Recognizing these conditions before someone is injured is an important part of preventing sharps exposures.","s":74.894,"e":81.708}],"env":""},"manufacturing/c2rem":{"src":"manufacturing-c2rem.m4a","dur":74.87,"sents":[{"p":0,"w":"DANA","t":"Let’s talk about a sharps container that’s at the fill line.","s":0.0,"e":3.046},{"p":0,"w":"DANA","t":"There are two separate conditions in this one, so let’s take them one at a time.","s":3.366,"e":7.683},{"p":1,"w":"RAY","t":"Good idea.","s":8.183,"e":9.333},{"p":1,"w":"RAY","t":"First one.","s":9.653,"e":10.836},{"p":1,"w":"RAY","t":"You arrive at a designated sharps container and notice that several used sharps are already crowded near the top.","s":11.156,"e":18.162},{"p":1,"w":"RAY","t":"One is resting near the opening, leaving little room to add another safely.","s":18.482,"e":23.28},{"p":2,"w":"DANA","t":"So what happens if you try?","s":23.78,"e":25.455},{"p":3,"w":"RAY","t":"Pressing the sharps down, or trying to fit another one in, could bring your hand into contact with a used sharp.","s":25.955,"e":33.324},{"p":4,"w":"DANA","t":"Your hand.","s":33.824,"e":34.408},{"p":5,"w":"RAY","t":"Yours.","s":34.908,"e":35.819},{"p":5,"w":"RAY","t":"So when a container reaches its fill line, it should be treated as full and should not be used.","s":36.139,"e":41.898},{"p":5,"w":"RAY","t":"Use another designated sharps container instead.","s":42.218,"e":45.88},{"p":6,"w":"DANA","t":"Second condition.","s":46.38,"e":47.428},{"p":7,"w":"RAY","t":"A sharp can also become a hazard when it is left somewhere it doesn’t belong.","s":47.928,"e":52.758},{"p":7,"w":"RAY","t":"On a work surface.","s":53.078,"e":54.693},{"p":7,"w":"RAY","t":"Concealed in other material.","s":55.013,"e":57.102},{"p":7,"w":"RAY","t":"Placed in general waste.","s":57.422,"e":59.27},{"p":7,"w":"RAY","t":"Any of those can expose someone who doesn’t expect it to be there.","s":59.59,"e":63.637},{"p":8,"w":"DANA","t":"And what connects them?","s":64.137,"e":65.283},{"p":9,"w":"RAY","t":"Whether the hazard is a full container or a misplaced sharp, recognizing the unsafe condition is the first step in preventing a sharps injury.","s":65.783,"e":74.549}],"env":""},"manufacturing/c2up":{"src":"manufacturing-c2up.m4a","dur":76.11,"sents":[{"p":0,"w":"DANA","t":"Let’s talk about when hazards aren’t as obvious.","s":0.0,"e":2.454},{"p":0,"w":"DANA","t":"Ray, take me through it.","s":2.774,"e":4.29},{"p":1,"w":"RAY","t":"You’re carrying a used sharp toward a designated sharps container on the production floor.","s":4.79,"e":10.405},{"p":1,"w":"RAY","t":"As you approach, the container is nearing its marked fill line.","s":10.725,"e":14.868},{"p":2,"w":"DANA","t":"Nearing.","s":15.368,"e":15.862},{"p":2,"w":"DANA","t":"Not at it.","s":16.182,"e":16.78},{"p":3,"w":"RAY","t":"Nearing.","s":17.28,"e":18.191},{"p":3,"w":"RAY","t":"There appears to be room for another sharp — but the contents are already crowded near the top.","s":18.511,"e":24.525},{"p":4,"w":"DANA","t":"Okay.","s":25.025,"e":25.599},{"p":5,"w":"RAY","t":"And on the way, you notice something partially concealed in a general-waste bin.","s":26.099,"e":31.106},{"p":5,"w":"RAY","t":"It looks like it could be a piece of contaminated glass.","s":31.426,"e":35.056},{"p":5,"w":"RAY","t":"You can’t tell without disturbing the contents.","s":35.376,"e":38.671},{"p":6,"w":"DANA","t":"So now I have two maybes.","s":39.171,"e":40.834},{"p":6,"w":"DANA","t":"And my first read is that neither one is mine to act on yet.","s":41.154,"e":44.18},{"p":7,"w":"RAY","t":"That’s a common read, and it’s worth slowing down on.","s":44.68,"e":48.295},{"p":7,"w":"RAY","t":"Sharps hazards aren’t always obvious.","s":48.615,"e":51.414},{"p":7,"w":"RAY","t":"A container nearing capacity can leave less room to place another sharp safely.","s":51.734,"e":56.964},{"p":8,"w":"DANA","t":"And the one in the bin, even though nobody’s confirmed what it is?","s":57.464,"e":60.733},{"p":9,"w":"RAY","t":"A possible sharp concealed in general waste can put someone at risk if the material is disturbed or handled without recognizing what may be inside.","s":61.233,"e":70.336},{"p":9,"w":"RAY","t":"Recognizing the warning signs matters even when the hazard isn’t immediately clear.","s":70.656,"e":75.79}],"env":""},"manufacturing/controls":{"src":"manufacturing-controls.m4a","dur":77.84,"sents":[{"p":0,"w":"DANA","t":"Why the container beats the gloves.","s":0.0,"e":1.871},{"p":0,"w":"DANA","t":"Ray, I want to take the other side of this for a minute.","s":2.191,"e":5.217},{"p":1,"w":"RAY","t":"Please.","s":5.717,"e":6.59},{"p":2,"w":"DANA","t":"A facility is looking for ways to better protect employees who may come into contact with used sharps.","s":7.09,"e":12.578},{"p":2,"w":"DANA","t":"Two options.","s":12.898,"e":13.699},{"p":2,"w":"DANA","t":"One, provide heavier protective gloves.","s":14.019,"e":16.657},{"p":2,"w":"DANA","t":"Two, make designated sharps containers more accessible throughout the facility.","s":16.977,"e":21.508},{"p":3,"w":"RAY","t":"Both on the table.","s":22.008,"e":23.541},{"p":4,"w":"DANA","t":"And I’d take the gloves.","s":24.041,"e":25.35},{"p":4,"w":"DANA","t":"Gloves are on the person, everywhere they go.","s":25.67,"e":28.134},{"p":4,"w":"DANA","t":"The container only works if somebody walks to it.","s":28.454,"e":30.997},{"p":5,"w":"RAY","t":"That’s a reasonable case, and both can provide protection.","s":31.497,"e":35.736},{"p":5,"w":"RAY","t":"Where they differ is how they control the hazard.","s":36.056,"e":39.126},{"p":6,"w":"DANA","t":"Go on.","s":39.626,"e":40.214},{"p":7,"w":"RAY","t":"Heavy-duty gloves can help protect against cuts, punctures, and exposure.","s":40.714,"e":46.185},{"p":7,"w":"RAY","t":"But even thick gloves can be penetrated by a needle.","s":46.505,"e":49.814},{"p":8,"w":"DANA","t":"So the glove protects the person.","s":50.314,"e":52.163},{"p":8,"w":"DANA","t":"At least usually.","s":52.483,"e":53.455},{"p":9,"w":"RAY","t":"A designated sharps container is an engineering control.","s":53.955,"e":57.905},{"p":9,"w":"RAY","t":"It contains the sharp after disposal, reducing the chance that another person will come into contact with it.","s":58.225,"e":65.312},{"p":9,"w":"RAY","t":"That provides stronger protection against needlestick injuries than relying on PPE alone.","s":65.632,"e":71.871},{"p":10,"w":"DANA","t":"One protects the person.","s":72.371,"e":73.801},{"p":10,"w":"DANA","t":"One contains the hazard.","s":74.121,"e":75.551},{"p":11,"w":"RAY","t":"That’s the difference.","s":76.051,"e":77.522}],"env":""},"manufacturing/case3":{"src":"manufacturing-case3.m4a","dur":69.07,"sents":[{"p":0,"w":"DANA","t":"This one is an interview.","s":0.0,"e":1.229},{"p":0,"w":"DANA","t":"Jacob, thank you for doing this.","s":1.549,"e":3.563},{"p":1,"w":"JACOB","t":"Sure.","s":4.063,"e":4.893},{"p":2,"w":"DANA","t":"Tell me what you do.","s":5.393,"e":6.473},{"p":3,"w":"JACOB","t":"I collect the bags.","s":6.973,"e":8.684},{"p":3,"w":"JACOB","t":"Sanitation.","s":9.004,"e":10.394},{"p":4,"w":"DANA","t":"Take me to that day.","s":10.894,"e":12.02},{"p":5,"w":"JACOB","t":"There’s a guy on the line.","s":12.52,"e":14.391},{"p":5,"w":"JACOB","t":"Chris.","s":14.711,"e":15.568},{"p":5,"w":"JACOB","t":"He manages his diabetes with insulin.","s":15.888,"e":18.702},{"p":5,"w":"JACOB","t":"That afternoon he couldn’t find a sharps container nearby.","s":19.022,"e":23.133},{"p":5,"w":"JACOB","t":"He was in the middle of a task.","s":23.453,"e":25.548},{"p":5,"w":"JACOB","t":"So just that once, he tossed the used needle into the general trash.","s":25.868,"e":30.426},{"p":6,"w":"DANA","t":"And you came through after.","s":30.926,"e":32.211},{"p":7,"w":"JACOB","t":"I came through after.","s":32.711,"e":34.422},{"p":7,"w":"JACOB","t":"I picked up the bag.","s":34.742,"e":36.532},{"p":7,"w":"JACOB","t":"The needle stuck me through the bag.","s":36.852,"e":39.187},{"p":8,"w":"DANA","t":"Did you see it?","s":39.687,"e":40.457},{"p":9,"w":"JACOB","t":"No.","s":40.957,"e":41.739},{"p":9,"w":"JACOB","t":"I never used that needle.","s":42.059,"e":43.945},{"p":9,"w":"JACOB","t":"I never even saw it.","s":44.265,"e":45.96},{"p":10,"w":"DANA","t":"And a needlestick carries more than the stick.","s":46.46,"e":48.523},{"p":11,"w":"JACOB","t":"A needlestick can expose you to bloodborne pathogens.","s":49.023,"e":52.733},{"p":11,"w":"JACOB","t":"HIV.","s":53.053,"e":53.932},{"p":11,"w":"JACOB","t":"Hepatitis B.","s":54.252,"e":55.787},{"p":11,"w":"JACOB","t":"Hepatitis C.","s":56.107,"e":57.657},{"p":13,"w":"DANA","t":"How do you think about it now?","s":59.357,"e":61.026},{"p":14,"w":"JACOB","t":"The shortcut was his.","s":61.526,"e":63.22},{"p":14,"w":"JACOB","t":"The risk became mine.","s":63.54,"e":65.331},{"p":14,"w":"JACOB","t":"One decision became someone else’s injury.","s":65.651,"e":68.753}],"env":""},"manufacturing/case3rf":{"src":"manufacturing-case3rf.m4a","dur":109.24,"sents":[{"p":0,"w":"DANA","t":"This one is an interview.","s":0.0,"e":1.229},{"p":0,"w":"DANA","t":"Jacob, thank you for doing this.","s":1.549,"e":3.563},{"p":1,"w":"JACOB","t":"Sure.","s":4.063,"e":4.893},{"p":2,"w":"DANA","t":"Tell me what you do.","s":5.393,"e":6.473},{"p":3,"w":"JACOB","t":"I collect the bags.","s":6.973,"e":8.684},{"p":3,"w":"JACOB","t":"Sanitation.","s":9.004,"e":10.394},{"p":4,"w":"DANA","t":"Take me to that day.","s":10.894,"e":12.02},{"p":5,"w":"JACOB","t":"There’s a guy on the line.","s":12.52,"e":14.391},{"p":5,"w":"JACOB","t":"Chris.","s":14.711,"e":15.568},{"p":5,"w":"JACOB","t":"He manages his diabetes with insulin.","s":15.888,"e":18.702},{"p":5,"w":"JACOB","t":"That afternoon he couldn’t find a sharps container nearby.","s":19.022,"e":23.133},{"p":5,"w":"JACOB","t":"He was in the middle of a task.","s":23.453,"e":25.548},{"p":5,"w":"JACOB","t":"So just that once, he tossed the used needle into the general trash.","s":25.868,"e":30.426},{"p":6,"w":"DANA","t":"And you came through after.","s":30.926,"e":32.211},{"p":7,"w":"JACOB","t":"I came through after.","s":32.711,"e":34.422},{"p":7,"w":"JACOB","t":"I picked up that bag.","s":34.742,"e":36.597},{"p":7,"w":"JACOB","t":"The needle stuck me through it.","s":36.917,"e":38.787},{"p":8,"w":"DANA","t":"Did you see it?","s":39.287,"e":40.057},{"p":9,"w":"JACOB","t":"No.","s":40.557,"e":41.339},{"p":9,"w":"JACOB","t":"I never used that needle.","s":41.659,"e":43.545},{"p":9,"w":"JACOB","t":"I never even saw it.","s":43.865,"e":45.56},{"p":10,"w":"DANA","t":"What happened from there?","s":46.06,"e":47.165},{"p":11,"w":"JACOB","t":"It didn’t end with the stick.","s":47.665,"e":49.568},{"p":11,"w":"JACOB","t":"It meant reporting the injury.","s":49.888,"e":52.014},{"p":11,"w":"JACOB","t":"A medical evaluation.","s":52.334,"e":54.333},{"p":11,"w":"JACOB","t":"Blood tests.","s":54.653,"e":55.914},{"p":11,"w":"JACOB","t":"And weeks of waiting to learn whether I’d been exposed to HIV, hepatitis B, or hepatitis C.","s":56.234,"e":63.193},{"p":12,"w":"DANA","t":"Weeks.","s":63.693,"e":64.252},{"p":13,"w":"JACOB","t":"Weeks.","s":64.752,"e":65.631},{"p":13,"w":"JACOB","t":"And my family waited them with me.","s":65.951,"e":68.333},{"p":13,"w":"JACOB","t":"The same question sitting at our dinner table every night.","s":68.653,"e":72.252},{"p":15,"w":"DANA","t":"You had no part in the decision.","s":73.952,"e":75.616},{"p":16,"w":"JACOB","t":"No part in it.","s":76.116,"e":77.459},{"p":16,"w":"JACOB","t":"And I’m the one who was left carrying it.","s":77.779,"e":80.369},{"p":16,"w":"JACOB","t":"Me, and the people who love me.","s":80.689,"e":83.023},{"p":16,"w":"JACOB","t":"I couldn’t see the needle.","s":83.343,"e":85.166},{"p":16,"w":"JACOB","t":"I couldn’t avoid the shortcut.","s":85.486,"e":87.804},{"p":16,"w":"JACOB","t":"I couldn’t choose differently.","s":88.124,"e":90.155},{"p":17,"w":"DANA","t":"What would you want someone to take from it?","s":90.655,"e":92.596},{"p":18,"w":"JACOB","t":"Chris saved himself a trip to the sharps container.","s":93.096,"e":96.641},{"p":18,"w":"JACOB","t":"I inherited the risk.","s":96.961,"e":98.767},{"p":18,"w":"JACOB","t":"That’s how far one disposal choice can reach.","s":99.087,"e":102.126},{"p":18,"w":"JACOB","t":"And if it had been you waiting on those results — you, or someone in your family — how would those weeks have felt?","s":102.446,"e":108.925}],"env":""},"manufacturing/debrief":{"src":"manufacturing-debrief.m4a","dur":61.83,"sents":[{"p":0,"w":"DANA","t":"The shortcut is the exception.","s":0.0,"e":1.603},{"p":0,"w":"DANA","t":"Ray, I want to say the common assumption out loud.","s":1.923,"e":4.832},{"p":1,"w":"RAY","t":"Say it.","s":5.332,"e":6.275},{"p":2,"w":"DANA","t":"There’s a common assumption that when a sharps container isn’t nearby, everyone takes the shortcut and drops the sharp in the nearest trash.","s":6.775,"e":14.03},{"p":2,"w":"DANA","t":"And making the trip to a designated container can feel unrealistic when work is moving quickly.","s":14.35,"e":19.42},{"p":3,"w":"RAY","t":"That’s the assumption.","s":19.92,"e":21.582},{"p":3,"w":"RAY","t":"And that shortcut isn’t necessarily the norm.","s":21.902,"e":25.069},{"p":4,"w":"DANA","t":"Meaning there’s a number.","s":25.569,"e":26.653},{"p":5,"w":"RAY","t":"There’s a number.","s":27.153,"e":28.383},{"p":5,"w":"RAY","t":"In a U.S. study, ninety-two point seven percent of workers surveyed reported always disposing of sharp objects in a sharps container.","s":28.703,"e":37.358},{"p":6,"w":"DANA","t":"Ninety-two point seven.","s":37.858,"e":39.256},{"p":7,"w":"RAY","t":"Always.","s":39.756,"e":40.666},{"p":8,"w":"DANA","t":"So why does it feel like the reverse?","s":41.166,"e":43.189},{"p":9,"w":"RAY","t":"The shortcut stands out because it’s memorable, and because of what can happen when someone takes it.","s":43.689,"e":49.832},{"p":9,"w":"RAY","t":"Not because it’s how the work normally gets done.","s":50.152,"e":53.238},{"p":10,"w":"DANA","t":"So the version we tell each other is the exception.","s":53.738,"e":56.342},{"p":11,"w":"RAY","t":"Safe disposal is the norm, even when the container isn’t convenient.","s":56.842,"e":61.513}],"env":""},"manufacturing/debriefrf":{"src":"manufacturing-debriefrf.m4a","dur":60.53,"sents":[{"p":0,"w":"DANA","t":"Memorable isn’t the same as normal.","s":0.0,"e":1.757},{"p":0,"w":"DANA","t":"Ray, I want to stay with this one, because it’s a belief a lot of people hold.","s":2.077,"e":6.636},{"p":1,"w":"RAY","t":"Start with why people believe it.","s":7.136,"e":9.374},{"p":2,"w":"DANA","t":"When a sharps container isn’t nearby, it can feel like taking the shortcut is simply what people do.","s":9.874,"e":15.484},{"p":2,"w":"DANA","t":"And that expecting everyone to make the trip is unrealistic.","s":15.804,"e":18.947},{"p":3,"w":"RAY","t":"That’s how it feels.","s":19.447,"e":21.013},{"p":3,"w":"RAY","t":"And what stands out isn’t always what’s most common.","s":21.333,"e":24.708},{"p":4,"w":"DANA","t":"Give me the number.","s":25.208,"e":26.094},{"p":5,"w":"RAY","t":"In a U.S. study, ninety-two point seven percent of workers surveyed reported always disposing of sharp objects in a sharps container.","s":26.594,"e":35.248},{"p":6,"w":"DANA","t":"That’s higher than I would have guessed.","s":35.748,"e":37.384},{"p":7,"w":"RAY","t":"The shortcut feels common because it’s the behavior that gets noticed and remembered.","s":37.884,"e":43.131},{"p":7,"w":"RAY","t":"The one time someone cuts a corner becomes the story people retell.","s":43.451,"e":48.041},{"p":7,"w":"RAY","t":"The routine trips to the sharps container don’t.","s":48.361,"e":51.544},{"p":8,"w":"DANA","t":"So memorable isn’t the same as normal.","s":52.044,"e":54.044},{"p":9,"w":"RAY","t":"Safe disposal is the expected practice, even when the container isn’t convenient.","s":54.544,"e":60.206}],"env":""},"public/c1base":{"src":"public-c1base.m4a","dur":80.23,"sents":[{"p":0,"w":"DANA","t":"The needle at the counter.","s":0.0,"e":1.185},{"p":0,"w":"DANA","t":"Ray, set it up for me.","s":1.505,"e":3.102},{"p":1,"w":"RAY","t":"You’ve just recovered a used hypodermic needle from a subject’s property at the booking counter.","s":3.602,"e":9.617},{"p":2,"w":"DANA","t":"So it’s already in your hand.","s":10.117,"e":11.734},{"p":3,"w":"RAY","t":"In your gloved hand.","s":12.234,"e":13.928},{"p":3,"w":"RAY","t":"And the designated sharps container is across the intake area.","s":14.248,"e":18.487},{"p":4,"w":"DANA","t":"Help me with the risk.","s":18.987,"e":20.144},{"p":4,"w":"DANA","t":"It’s one needle.","s":20.464,"e":21.274},{"p":5,"w":"RAY","t":"A used needle retains a small amount of blood after use.","s":21.774,"e":25.596},{"p":5,"w":"RAY","t":"And its sharpness makes it likely to penetrate someone else’s skin and expose them to that retained blood.","s":25.916,"e":32.427},{"p":6,"w":"DANA","t":"Does it matter whether it looks contaminated?","s":32.927,"e":35.15},{"p":7,"w":"RAY","t":"It doesn’t.","s":35.65,"e":36.753},{"p":7,"w":"RAY","t":"Whether or not it looks contaminated, a needle left on the counter or dropped into a property tray is a hazard to the next person who reaches for that spot.","s":37.073,"e":46.495},{"p":7,"w":"RAY","t":"That’s why the safe-handling procedure applies to every sharp, every time.","s":46.815,"e":51.998},{"p":8,"w":"DANA","t":"So what is the procedure?","s":52.498,"e":53.859},{"p":8,"w":"DANA","t":"Say it plainly.","s":54.179,"e":55.134},{"p":9,"w":"RAY","t":"Four things.","s":55.634,"e":56.913},{"p":9,"w":"RAY","t":"Plan how the sharp will be disposed of before you handle it.","s":57.233,"e":61.129},{"p":9,"w":"RAY","t":"Use a needle alternative when one is available.","s":61.449,"e":64.424},{"p":9,"w":"RAY","t":"Activate any available safety feature.","s":64.744,"e":67.654},{"p":9,"w":"RAY","t":"And once it’s been used — don’t recap it, don’t bend it, don’t break it.","s":67.974,"e":73.189},{"p":9,"w":"RAY","t":"It goes directly into a designated sharps container.","s":73.509,"e":77.204},{"p":10,"w":"DANA","t":"Directly.","s":77.704,"e":78.313},{"p":11,"w":"RAY","t":"Directly.","s":78.813,"e":79.914}],"env":""},"public/c1rem":{"src":"public-c1rem.m4a","dur":65.69,"sents":[{"p":0,"w":"DANA","t":"The needle at the counter.","s":0.0,"e":1.185},{"p":0,"w":"DANA","t":"Let’s take this one slowly.","s":1.505,"e":3.042},{"p":1,"w":"RAY","t":"You’ve recovered a used needle during a property search.","s":3.542,"e":7.044},{"p":1,"w":"RAY","t":"It’s still in your gloved hand while you decide how to handle it before moving on.","s":7.364,"e":12.291},{"p":2,"w":"DANA","t":"My instinct is to make it safer first.","s":12.791,"e":15.036},{"p":2,"w":"DANA","t":"Recap it.","s":15.356,"e":16.048},{"p":2,"w":"DANA","t":"Or set it aside.","s":16.368,"e":17.394},{"p":3,"w":"RAY","t":"That instinct makes sense — both of those feel like the responsible move.","s":17.894,"e":22.628},{"p":3,"w":"RAY","t":"What they don’t do is properly contain the sharp.","s":22.948,"e":26.291},{"p":3,"w":"RAY","t":"That’s the distinction.","s":26.611,"e":28.257},{"p":4,"w":"DANA","t":"What if there’s no container right there?","s":28.757,"e":30.675},{"p":5,"w":"RAY","t":"If no designated sharps container is immediately available, don’t place the needle in general waste.","s":31.175,"e":37.814},{"p":5,"w":"RAY","t":"And don’t improvise a wrapping out of soft material — a paper towel, a plastic bag.","s":38.134,"e":44.02},{"p":6,"w":"DANA","t":"So what’s left?","s":44.52,"e":45.487},{"p":7,"w":"RAY","t":"The rule underneath stays the same.","s":45.987,"e":48.354},{"p":7,"w":"RAY","t":"Once a sharp is used, don’t recap it, bend it, or break it.","s":48.674,"e":53.44},{"p":7,"w":"RAY","t":"Don’t leave it on a work surface, and don’t place it in general waste.","s":53.76,"e":58.333},{"p":7,"w":"RAY","t":"The safe-handling procedure is to seek a designated sharps container and move the sharp directly into it.","s":58.653,"e":65.372}],"env":""},"public/c1up":{"src":"public-c1up.m4a","dur":69.21,"sents":[{"p":0,"w":"DANA","t":"When the container is across the room.","s":0.0,"e":1.929},{"p":0,"w":"DANA","t":"Ray, set it up for me.","s":2.249,"e":3.847},{"p":1,"w":"RAY","t":"You’ve just recovered a used hypodermic needle from a subject’s property at the booking counter.","s":4.347,"e":10.361},{"p":1,"w":"RAY","t":"The designated sharps container is at the far end of the intake area.","s":10.681,"e":15.192},{"p":1,"w":"RAY","t":"The queue behind you is backing up.","s":15.512,"e":17.879},{"p":1,"w":"RAY","t":"And another officer is calling you over to help with a subject in the next room.","s":18.199,"e":23.253},{"p":2,"w":"DANA","t":"That’s a real situation.","s":23.753,"e":25.145},{"p":3,"w":"RAY","t":"That’s the situation.","s":25.645,"e":27.372},{"p":4,"w":"DANA","t":"And here’s my honest read — setting it down on the counter doesn’t feel careless.","s":27.872,"e":32.232},{"p":4,"w":"DANA","t":"I can see exactly where it is.","s":32.552,"e":34.417},{"p":4,"w":"DANA","t":"I’ll deal with it as soon as I’m back.","s":34.737,"e":36.591},{"p":5,"w":"RAY","t":"That’s exactly how it feels.","s":37.091,"e":39.346},{"p":5,"w":"RAY","t":"Nothing about that feels careless.","s":39.666,"e":42.096},{"p":6,"w":"DANA","t":"And yet.","s":42.596,"e":43.092},{"p":7,"w":"RAY","t":"The safe-handling procedure doesn’t change when the room gets busy.","s":43.592,"e":47.814},{"p":7,"w":"RAY","t":"Once a sharp is used — don’t recap it, don’t bend it, don’t break it, and don’t set it aside for later.","s":48.134,"e":55.461},{"p":7,"w":"RAY","t":"It goes directly into a designated sharps container.","s":55.781,"e":59.475},{"p":8,"w":"DANA","t":"Even briefly.","s":59.975,"e":60.819},{"p":9,"w":"RAY","t":"Leaving that needle on the counter, even briefly, creates a hazard for anyone who reaches for that spot before you return.","s":61.319,"e":68.886}],"env":""},"public/c2base":{"src":"public-c2base.m4a","dur":81.69,"sents":[{"p":0,"w":"DANA","t":"Let’s talk about a sharps container that’s at the fill line.","s":0.0,"e":3.046},{"p":0,"w":"DANA","t":"Ray, this is all about what you notice when you’re following procedure.","s":3.366,"e":7.065},{"p":1,"w":"RAY","t":"It is.","s":7.565,"e":8.412},{"p":1,"w":"RAY","t":"Knowing what to do is one thing.","s":8.732,"e":10.906},{"p":1,"w":"RAY","t":"Spotting the condition is a separate skill.","s":11.226,"e":13.929},{"p":2,"w":"DANA","t":"Give me the scene.","s":14.429,"e":15.361},{"p":3,"w":"RAY","t":"You’re carrying a used needle recovered during a property search to the designated sharps container in the station’s processing area.","s":15.861,"e":23.828},{"p":3,"w":"RAY","t":"As you approach, you notice the container has reached its fill line.","s":24.148,"e":28.45},{"p":4,"w":"DANA","t":"At the line.","s":28.95,"e":29.678},{"p":5,"w":"RAY","t":"At the line.","s":30.178,"e":31.409},{"p":5,"w":"RAY","t":"And on the way there, you passed a used syringe sitting in a general-waste bin.","s":31.729,"e":36.607},{"p":6,"w":"DANA","t":"Two very different situations.","s":37.107,"e":38.919},{"p":7,"w":"RAY","t":"Both present a sharps hazard, but for different reasons.","s":39.419,"e":43.512},{"p":8,"w":"DANA","t":"Start with the container.","s":44.012,"e":45.303},{"p":8,"w":"DANA","t":"Why does reaching the line count?","s":45.623,"e":47.308},{"p":9,"w":"RAY","t":"A sharps container at its fill line should no longer be used, because there’s less room to place another sharp safely without coming into contact with the sharps already inside.","s":47.808,"e":58.991},{"p":10,"w":"DANA","t":"And the syringe in the bin?","s":59.491,"e":60.637},{"p":11,"w":"RAY","t":"A sharp left where it doesn’t belong — on a work surface, concealed in other material, or mixed into general waste — can put the next person who encounters it at risk.","s":61.137,"e":72.031},{"p":12,"w":"DANA","t":"So the skill here is seeing it.","s":72.531,"e":74.055},{"p":13,"w":"RAY","t":"Recognizing these conditions before someone is injured is an important part of preventing sharps exposures.","s":74.555,"e":81.369}],"env":""},"public/c2rem":{"src":"public-c2rem.m4a","dur":74.87,"sents":[{"p":0,"w":"DANA","t":"Let’s talk about a sharps container that’s at the fill line.","s":0.0,"e":3.046},{"p":0,"w":"DANA","t":"There are two separate conditions in this one, so let’s take them one at a time.","s":3.366,"e":7.683},{"p":1,"w":"RAY","t":"Good idea.","s":8.183,"e":9.333},{"p":1,"w":"RAY","t":"First one.","s":9.653,"e":10.836},{"p":1,"w":"RAY","t":"You arrive at a designated sharps container and notice that several used sharps are already crowded near the top.","s":11.156,"e":18.162},{"p":1,"w":"RAY","t":"One is resting near the opening, leaving little room to add another safely.","s":18.482,"e":23.28},{"p":2,"w":"DANA","t":"So what happens if you try?","s":23.78,"e":25.455},{"p":3,"w":"RAY","t":"Pressing the sharps down, or trying to fit another one in, could bring your hand into contact with a used sharp.","s":25.955,"e":33.324},{"p":4,"w":"DANA","t":"Your hand.","s":33.824,"e":34.408},{"p":5,"w":"RAY","t":"Yours.","s":34.908,"e":35.819},{"p":5,"w":"RAY","t":"So when a container reaches its fill line, it should be treated as full and should not be used.","s":36.139,"e":41.898},{"p":5,"w":"RAY","t":"Use another designated sharps container instead.","s":42.218,"e":45.88},{"p":6,"w":"DANA","t":"Second condition.","s":46.38,"e":47.428},{"p":7,"w":"RAY","t":"A sharp can also become a hazard when it is left somewhere it doesn’t belong.","s":47.928,"e":52.758},{"p":7,"w":"RAY","t":"On a work surface.","s":53.078,"e":54.693},{"p":7,"w":"RAY","t":"Concealed in other material.","s":55.013,"e":57.102},{"p":7,"w":"RAY","t":"Placed in general waste.","s":57.422,"e":59.27},{"p":7,"w":"RAY","t":"Any of those can expose someone who doesn’t expect it to be there.","s":59.59,"e":63.637},{"p":8,"w":"DANA","t":"And what connects them?","s":64.137,"e":65.283},{"p":9,"w":"RAY","t":"Whether the hazard is a full container or a misplaced sharp, recognizing the unsafe condition is the first step in preventing a sharps injury.","s":65.783,"e":74.549}],"env":""},"public/c2up":{"src":"public-c2up.m4a","dur":76.03,"sents":[{"p":0,"w":"DANA","t":"Let’s talk about when hazards aren’t as obvious.","s":0.0,"e":2.454},{"p":0,"w":"DANA","t":"Ray, take me through it.","s":2.774,"e":4.29},{"p":1,"w":"RAY","t":"You’re carrying a recovered sharp toward the designated sharps container in the station’s processing area.","s":4.79,"e":11.269},{"p":1,"w":"RAY","t":"As you approach, the container is nearing its marked fill line.","s":11.589,"e":15.732},{"p":2,"w":"DANA","t":"Nearing.","s":16.232,"e":16.726},{"p":2,"w":"DANA","t":"Not at it.","s":17.046,"e":17.644},{"p":3,"w":"RAY","t":"Nearing.","s":18.144,"e":19.055},{"p":3,"w":"RAY","t":"There appears to be room for another sharp — but the contents are already crowded near the top.","s":19.375,"e":25.389},{"p":4,"w":"DANA","t":"Okay.","s":25.889,"e":26.463},{"p":5,"w":"RAY","t":"And on the way, you notice something partially concealed in a general-waste bin.","s":26.963,"e":31.97},{"p":5,"w":"RAY","t":"It looks like it could be a used syringe.","s":32.29,"e":34.976},{"p":5,"w":"RAY","t":"You can’t tell without disturbing the contents.","s":35.296,"e":38.591},{"p":6,"w":"DANA","t":"So now I have two maybes.","s":39.091,"e":40.754},{"p":6,"w":"DANA","t":"And my first read is that neither one is mine to act on yet.","s":41.074,"e":44.1},{"p":7,"w":"RAY","t":"That’s a common read, and it’s worth slowing down on.","s":44.6,"e":48.215},{"p":7,"w":"RAY","t":"Sharps hazards aren’t always obvious.","s":48.535,"e":51.334},{"p":7,"w":"RAY","t":"A container nearing capacity can leave less room to place another sharp safely.","s":51.654,"e":56.884},{"p":8,"w":"DANA","t":"And the one in the bin, even though nobody’s confirmed what it is?","s":57.384,"e":60.653},{"p":9,"w":"RAY","t":"A possible sharp concealed in general waste can put someone at risk if the material is disturbed or handled without recognizing what may be inside.","s":61.153,"e":70.256},{"p":9,"w":"RAY","t":"Recognizing the warning signs matters even when the hazard isn’t immediately clear.","s":70.576,"e":75.71}],"env":""},"public/controls":{"src":"public-controls.m4a","dur":78.89,"sents":[{"p":0,"w":"DANA","t":"Why the container beats the gloves.","s":0.0,"e":1.871},{"p":0,"w":"DANA","t":"Ray, I want to take the other side of this for a minute.","s":2.191,"e":5.217},{"p":1,"w":"RAY","t":"Please.","s":5.717,"e":6.59},{"p":2,"w":"DANA","t":"An agency is looking for ways to better protect officers who may come into contact with used sharps.","s":7.09,"e":12.555},{"p":2,"w":"DANA","t":"Two options.","s":12.875,"e":13.676},{"p":2,"w":"DANA","t":"One, issue heavier protective gloves.","s":13.996,"e":16.529},{"p":2,"w":"DANA","t":"Two, make designated sharps containers more accessible throughout its stations and intake areas.","s":16.849,"e":22.355},{"p":3,"w":"RAY","t":"Both on the table.","s":22.855,"e":24.389},{"p":4,"w":"DANA","t":"And I’d take the gloves.","s":24.889,"e":26.197},{"p":4,"w":"DANA","t":"Gloves are on the officer, everywhere they go.","s":26.517,"e":29.086},{"p":4,"w":"DANA","t":"The container only works if somebody walks to it.","s":29.406,"e":31.949},{"p":5,"w":"RAY","t":"That’s a reasonable case, and both can provide protection.","s":32.449,"e":36.688},{"p":5,"w":"RAY","t":"Where they differ is how they control the hazard.","s":37.008,"e":40.078},{"p":6,"w":"DANA","t":"Go on.","s":40.578,"e":41.166},{"p":7,"w":"RAY","t":"Heavy-duty gloves can help protect against cuts, punctures, and exposure.","s":41.666,"e":47.137},{"p":7,"w":"RAY","t":"But even thick gloves can be penetrated by a needle.","s":47.457,"e":50.766},{"p":8,"w":"DANA","t":"So the glove protects the officer.","s":51.266,"e":53.208},{"p":8,"w":"DANA","t":"At least usually.","s":53.528,"e":54.5},{"p":9,"w":"RAY","t":"A designated sharps container is an engineering control.","s":55.0,"e":58.95},{"p":9,"w":"RAY","t":"It contains the sharp after disposal, reducing the chance that another person will come into contact with it.","s":59.27,"e":66.357},{"p":9,"w":"RAY","t":"That provides stronger protection against needlestick injuries than relying on PPE alone.","s":66.677,"e":72.915},{"p":10,"w":"DANA","t":"One protects the person.","s":73.415,"e":74.846},{"p":10,"w":"DANA","t":"One contains the hazard.","s":75.166,"e":76.596},{"p":11,"w":"RAY","t":"That’s the difference.","s":77.096,"e":78.566}],"env":""},"public/case3":{"src":"public-case3.m4a","dur":70.61,"sents":[{"p":0,"w":"DANA","t":"This one is an interview.","s":0.0,"e":1.229},{"p":0,"w":"DANA","t":"Jacob, thank you for doing this.","s":1.549,"e":3.563},{"p":1,"w":"JACOB","t":"Sure.","s":4.063,"e":4.893},{"p":2,"w":"DANA","t":"Tell me what you do.","s":5.393,"e":6.473},{"p":3,"w":"JACOB","t":"Custodial pickup.","s":6.973,"e":8.598},{"p":3,"w":"JACOB","t":"I collect the bags.","s":8.918,"e":10.628},{"p":4,"w":"DANA","t":"Take me to that day.","s":11.128,"e":12.254},{"p":5,"w":"JACOB","t":"There’s an officer, Chris.","s":12.754,"e":14.817},{"p":5,"w":"JACOB","t":"He recovered a used needle from a subject’s property during an arrest.","s":15.137,"e":19.712},{"p":5,"w":"JACOB","t":"He couldn’t find a sharps container nearby.","s":20.032,"e":23.294},{"p":5,"w":"JACOB","t":"He was in the middle of the intake.","s":23.614,"e":25.821},{"p":5,"w":"JACOB","t":"So just that once, he dropped the used needle into the general trash at the station.","s":26.141,"e":31.467},{"p":6,"w":"DANA","t":"And you came through after.","s":31.967,"e":33.253},{"p":7,"w":"JACOB","t":"I came through after.","s":33.753,"e":35.463},{"p":7,"w":"JACOB","t":"I picked up the bag.","s":35.783,"e":37.574},{"p":7,"w":"JACOB","t":"The needle stuck me through the bag.","s":37.894,"e":40.228},{"p":8,"w":"DANA","t":"Did you see it?","s":40.728,"e":41.498},{"p":9,"w":"JACOB","t":"No.","s":41.998,"e":42.78},{"p":9,"w":"JACOB","t":"I never handled the arrest.","s":43.1,"e":45.226},{"p":9,"w":"JACOB","t":"I never even saw the needle.","s":45.546,"e":47.497},{"p":10,"w":"DANA","t":"And a needlestick carries more than the stick.","s":47.997,"e":50.06},{"p":11,"w":"JACOB","t":"A needlestick can expose you to bloodborne pathogens.","s":50.56,"e":54.271},{"p":11,"w":"JACOB","t":"HIV.","s":54.591,"e":55.469},{"p":11,"w":"JACOB","t":"Hepatitis B.","s":55.789,"e":57.324},{"p":11,"w":"JACOB","t":"Hepatitis C.","s":57.644,"e":59.194},{"p":13,"w":"DANA","t":"How do you think about it now?","s":60.894,"e":62.563},{"p":14,"w":"JACOB","t":"The shortcut was his.","s":63.063,"e":64.757},{"p":14,"w":"JACOB","t":"The risk became mine.","s":65.077,"e":66.868},{"p":14,"w":"JACOB","t":"One decision became someone else’s injury.","s":67.188,"e":70.29}],"env":""},"public/case3rf":{"src":"public-case3rf.m4a","dur":110.14,"sents":[{"p":0,"w":"DANA","t":"This one is an interview.","s":0.0,"e":1.229},{"p":0,"w":"DANA","t":"Jacob, thank you for doing this.","s":1.549,"e":3.563},{"p":1,"w":"JACOB","t":"Sure.","s":4.063,"e":4.893},{"p":2,"w":"DANA","t":"Tell me what you do.","s":5.393,"e":6.473},{"p":3,"w":"JACOB","t":"Custodial pickup.","s":6.973,"e":8.598},{"p":3,"w":"JACOB","t":"I collect the bags.","s":8.918,"e":10.628},{"p":4,"w":"DANA","t":"Take me to that day.","s":11.128,"e":12.254},{"p":5,"w":"JACOB","t":"There’s an officer, Chris.","s":12.754,"e":14.817},{"p":5,"w":"JACOB","t":"He recovered a used needle from a subject’s property during an arrest.","s":15.137,"e":19.712},{"p":5,"w":"JACOB","t":"He couldn’t find a sharps container nearby.","s":20.032,"e":23.294},{"p":5,"w":"JACOB","t":"He was in the middle of the intake.","s":23.614,"e":25.821},{"p":5,"w":"JACOB","t":"So just that once, he dropped the used needle into the general trash at the station.","s":26.141,"e":31.467},{"p":6,"w":"DANA","t":"And you came through after.","s":31.967,"e":33.253},{"p":7,"w":"JACOB","t":"I came through after.","s":33.753,"e":35.463},{"p":7,"w":"JACOB","t":"I picked up that bag.","s":35.783,"e":37.638},{"p":7,"w":"JACOB","t":"The needle stuck me through it.","s":37.958,"e":39.828},{"p":8,"w":"DANA","t":"Did you see it?","s":40.328,"e":41.098},{"p":9,"w":"JACOB","t":"No.","s":41.598,"e":42.38},{"p":9,"w":"JACOB","t":"I never handled the arrest.","s":42.7,"e":44.827},{"p":9,"w":"JACOB","t":"I never even saw the needle.","s":45.147,"e":47.097},{"p":10,"w":"DANA","t":"What happened from there?","s":47.597,"e":48.702},{"p":11,"w":"JACOB","t":"It didn’t end with the stick.","s":49.202,"e":51.105},{"p":11,"w":"JACOB","t":"It meant reporting the injury.","s":51.425,"e":53.551},{"p":11,"w":"JACOB","t":"A medical evaluation.","s":53.871,"e":55.87},{"p":11,"w":"JACOB","t":"Blood tests.","s":56.19,"e":57.451},{"p":11,"w":"JACOB","t":"And weeks of waiting to learn whether I’d been exposed to HIV, hepatitis B, or hepatitis C.","s":57.771,"e":64.73},{"p":12,"w":"DANA","t":"Weeks.","s":65.23,"e":65.789},{"p":13,"w":"JACOB","t":"Weeks.","s":66.289,"e":67.168},{"p":13,"w":"JACOB","t":"And my family waited them with me.","s":67.488,"e":69.87},{"p":13,"w":"JACOB","t":"The same question sitting at our dinner table every night.","s":70.19,"e":73.789},{"p":15,"w":"DANA","t":"You had no part in the decision.","s":75.489,"e":77.153},{"p":16,"w":"JACOB","t":"No part in it.","s":77.653,"e":78.996},{"p":16,"w":"JACOB","t":"And I’m the one who was left carrying it, along with the people who love me.","s":79.316,"e":83.922},{"p":16,"w":"JACOB","t":"I couldn’t see the needle.","s":84.242,"e":86.065},{"p":16,"w":"JACOB","t":"I couldn’t avoid the shortcut.","s":86.385,"e":88.703},{"p":16,"w":"JACOB","t":"I couldn’t choose differently.","s":89.023,"e":91.054},{"p":17,"w":"DANA","t":"What would you want someone to take from it?","s":91.554,"e":93.495},{"p":18,"w":"JACOB","t":"Chris saved himself a trip to the sharps container.","s":93.995,"e":97.54},{"p":18,"w":"JACOB","t":"I inherited the risk.","s":97.86,"e":99.666},{"p":18,"w":"JACOB","t":"That’s how far one disposal choice can reach.","s":99.986,"e":103.025},{"p":18,"w":"JACOB","t":"And if it had been you waiting on those results — you, or someone in your family — how would those weeks have felt?","s":103.345,"e":109.824}],"env":""},"public/debrief":{"src":"public-debrief.m4a","dur":61.83,"sents":[{"p":0,"w":"DANA","t":"The shortcut is the exception.","s":0.0,"e":1.603},{"p":0,"w":"DANA","t":"Ray, I want to say the common assumption out loud.","s":1.923,"e":4.832},{"p":1,"w":"RAY","t":"Say it.","s":5.332,"e":6.275},{"p":2,"w":"DANA","t":"There’s a common assumption that when a sharps container isn’t nearby, everyone takes the shortcut and drops the sharp in the nearest trash.","s":6.775,"e":14.03},{"p":2,"w":"DANA","t":"And making the trip to a designated container can feel unrealistic when work is moving quickly.","s":14.35,"e":19.42},{"p":3,"w":"RAY","t":"That’s the assumption.","s":19.92,"e":21.582},{"p":3,"w":"RAY","t":"And that shortcut isn’t necessarily the norm.","s":21.902,"e":25.069},{"p":4,"w":"DANA","t":"Meaning there’s a number.","s":25.569,"e":26.653},{"p":5,"w":"RAY","t":"There’s a number.","s":27.153,"e":28.383},{"p":5,"w":"RAY","t":"In a U.S. study, ninety-two point seven percent of workers surveyed reported always disposing of sharp objects in a sharps container.","s":28.703,"e":37.358},{"p":6,"w":"DANA","t":"Ninety-two point seven.","s":37.858,"e":39.256},{"p":7,"w":"RAY","t":"Always.","s":39.756,"e":40.666},{"p":8,"w":"DANA","t":"So why does it feel like the reverse?","s":41.166,"e":43.189},{"p":9,"w":"RAY","t":"The shortcut stands out because it’s memorable, and because of what can happen when someone takes it.","s":43.689,"e":49.832},{"p":9,"w":"RAY","t":"Not because it’s how the work normally gets done.","s":50.152,"e":53.238},{"p":10,"w":"DANA","t":"So the version we tell each other is the exception.","s":53.738,"e":56.342},{"p":11,"w":"RAY","t":"Safe disposal is the norm, even when the container isn’t convenient.","s":56.842,"e":61.513}],"env":""},"public/debriefrf":{"src":"public-debriefrf.m4a","dur":60.53,"sents":[{"p":0,"w":"DANA","t":"Memorable isn’t the same as normal.","s":0.0,"e":1.757},{"p":0,"w":"DANA","t":"Ray, I want to stay with this one, because it’s a belief a lot of people hold.","s":2.077,"e":6.636},{"p":1,"w":"RAY","t":"Start with why people believe it.","s":7.136,"e":9.374},{"p":2,"w":"DANA","t":"When a sharps container isn’t nearby, it can feel like taking the shortcut is simply what people do.","s":9.874,"e":15.484},{"p":2,"w":"DANA","t":"And that expecting everyone to make the trip is unrealistic.","s":15.804,"e":18.947},{"p":3,"w":"RAY","t":"That’s how it feels.","s":19.447,"e":21.013},{"p":3,"w":"RAY","t":"And what stands out isn’t always what’s most common.","s":21.333,"e":24.708},{"p":4,"w":"DANA","t":"Give me the number.","s":25.208,"e":26.094},{"p":5,"w":"RAY","t":"In a U.S. study, ninety-two point seven percent of workers surveyed reported always disposing of sharp objects in a sharps container.","s":26.594,"e":35.248},{"p":6,"w":"DANA","t":"That’s higher than I would have guessed.","s":35.748,"e":37.384},{"p":7,"w":"RAY","t":"The shortcut feels common because it’s the behavior that gets noticed and remembered.","s":37.884,"e":43.131},{"p":7,"w":"RAY","t":"The one time someone cuts a corner becomes the story people retell.","s":43.451,"e":48.041},{"p":7,"w":"RAY","t":"The routine trips to the sharps container don’t.","s":48.361,"e":51.544},{"p":8,"w":"DANA","t":"So memorable isn’t the same as normal.","s":52.044,"e":54.044},{"p":9,"w":"RAY","t":"Safe disposal is the expected practice, even when the container isn’t convenient.","s":54.544,"e":60.206}],"env":""},"manufacturing/sting":{"src":"sting.m4a","dur":1.6,"sents":[],"env":"tusqotzwusqomkjhgfedcba9987766555444333222222111"}};
